/**
 * Crea el tema canónico tema-135: "La Ordenanza municipal de cementerios
 * de Zaragoza y la Ordenanza municipal fiscal nº 19/18 del Cementerio de
 * Torrero" y lo asigna como Tema 17 (bloque-2, numero=19) de la
 * oposición Oficial Cementerio (Ayto. Zaragoza).
 *
 * Corresponde al TEMA 17 oficial del Anexo I (bases2110.pdf): "Ordenanza
 * municipal de cementerios de Zaragoza. Ordenanza municipal fiscal para
 * la prestación de servicios en el cementerio de Torrero de Zaragoza nº
 * 19/18"
 *
 * Fuentes primarias verificadas mediante búsqueda en esta sesión de
 * trabajo (portal de normativa del Ayuntamiento de Zaragoza,
 * zaragoza.es/sede/servicio/normativa/862 y /3505):
 * - Ordenanza Municipal de Cementerios de Zaragoza: Título Preliminar
 *   (objeto, carácter y ámbito de aplicación; Registro Público de
 *   Cementerios; clases de unidades de enterramiento; respeto a la
 *   libertad ideológica y religiosa; derechos y deberes de las personas
 *   usuarias) y Título I, en tres capítulos (régimen y constitución del
 *   derecho funerario; transmisión del derecho funerario; modificación y
 *   extinción del derecho funerario). El derecho funerario se define
 *   como uso temporal y exclusivo de una unidad de enterramiento, cuya
 *   titularidad corresponde en todo caso al Ayuntamiento; existen tres
 *   tipos de concesión (5 años para nichos y enterramientos ordinarios,
 *   49 años para nichos y columbarios, 99 años para terrenos y
 *   construcciones de enterramientos, panteones y capillas), garantizados
 *   mediante inscripción en el Libro Registro del Cementerio y un título
 *   nominativo.
 * - Ordenanza Fiscal nº 19: tasas por la prestación de servicios o
 *   aprovechamientos especiales en el Cementerio Municipal de Torrero,
 *   citada por su nombre y función general, sin reproducir tarifas
 *   concretas no verificadas directamente en esta sesión (los importes
 *   se actualizan anualmente y no forman parte del contenido estable
 *   verificable a estos efectos).
 *
 * Tres secciones:
 * 1. objeto-ambito-registro-clases-enterramiento
 * 2. derecho-funerario-concesiones-transmision-extincion
 * 3. ordenanza-fiscal-19-tasas-servicios
 *
 * Uso: node --env-file=.env.local scripts/seed-tema-135-ordenanza-cementerios-fiscal.mjs
 */
const URL_BASE = process.env.NEXT_PUBLIC_SUPABASE_URL;
const SERVICE_KEY = process.env.SUPABASE_SERVICE_ROLE_KEY;

if (!URL_BASE || !SERVICE_KEY) {
  console.error("❌ Faltan NEXT_PUBLIC_SUPABASE_URL o SUPABASE_SERVICE_ROLE_KEY.");
  process.exit(1);
}

const HEADERS = { apikey: SERVICE_KEY, Authorization: `Bearer ${SERVICE_KEY}`, "Content-Type": "application/json" };
